using System;
using System.Drawing;
using System.IO;
using System.Reflection;
using System.Windows.Forms;
namespace Downfield {
public static partial class UiTests {
 static void ArcadeScreens(GameForm f,string evidence){
  Set(f,"matchFixture",-1);Call(f,"StartPractice");Simulation s=(Simulation)Get(f,"game");Tap(f,Keys.Space);Step(f,Keys.D1,true,1);Tap(f,Keys.T);Check(s.State==Phase.Flight&&s.Message=="THROWN AWAY"&&!s.Charging,"T / RS-click input throws away a charged pass");Step(f,Keys.D1,false,1);for(int i=0;i<40;i++)Step(f,Keys.None,false,1);Check(s.State==Phase.Dead&&s.LastRunoff==0,"throwaway UI finishes incomplete");
  Call(f,"StartPractice");Tap(f,Keys.Escape);Set(f,"selection",7);Call(f,"ActivateSelection");Check((string)Get(f,"screen")=="audio","Pause Settings opens volume mixer");GameAudio audio=(GameAudio)Get(f,"audio");Set(f,"selection",2);float original=audio.Mix.GetGain(2);Tap(f,Keys.Left);Check(audio.Mix.GetGain(2)<original&&(int)Get(f,"selection")==2,"left adjusts whistle volume without changing row");Tap(f,Keys.Enter);Check(audio.Mix.GetGain(2)==0,"A mutes whistle channel");typeof(GameForm).GetMethod("AudioMouse",flags,null,new Type[]{typeof(PointF)},null).Invoke(f,new object[]{new PointF(760,300)});Check(Math.Abs(audio.Mix.GetGain(2)-.5f)<.01f,"mouse mixer sets whistle level directly");audio.Mix.SetGain(2,0);audio.Muted=false;f.SavePreview(Path.Combine(evidence,"pause-settings.png"));Tap(f,Keys.Escape);Check((string)Get(f,"screen")=="pause","settings returns to paused game");Tap(f,Keys.Escape);bool muted=audio.Muted;Tap(f,Keys.M);Check(audio.Muted!=muted,"M / Xbox View toggles in-game mute");f.SavePreview(Path.Combine(evidence,"quick-mute.png"));typeof(GameForm).GetMethod("MouseMenu",flags).Invoke(f,new object[]{new Point(1180,137)});Check(audio.Muted==muted,"clickable HUD button toggles mute");
  Franchise club=Franchise.Create(new Profile(),new Roster());club.UserTeam=1;Set(f,"franchise",club);Call(f,"StartGame");s=(Simulation)Get(f,"game");Player p=s.Players[1];s.Controlled.HasBall=false;s.Controlled=p;p.HasBall=true;p.Z=31;s.State=Phase.Live;typeof(Simulation).GetMethod("Injure",flags).Invoke(s,new object[]{p,true});typeof(Simulation).GetMethod("EndPlay",flags).Invoke(s,new object[]{31f,"TACKLED",false});Set(f,"cameraZ",25f);for(int i=0;i<38;i++)s.Update(.05f,0,0);f.SavePreview(Path.Combine(evidence,"ambulance-arrival.png"));Check(s.AmbulanceActive&&p.KnockTime>0,"ambulance arrives while patient stays prone");for(int i=0;i<12;i++)s.Update(.05f,0,0);f.SavePreview(Path.Combine(evidence,"ambulance-pickup.png"));Check(s.AmbulanceLoaded,"stretcher pickup renders loaded patient");Tap(f,Keys.Enter);Check(!s.AmbulanceActive,"controller A skips ambulance timeout");int injuredId=p.ClubId;Tap(f,Keys.Enter);Check(s.State==Phase.PreSnap&&s.Players[1].ClubId!=injuredId,"continuing replaces injured starter");Set(f,"matchFixture",-1);Set(f,"screen","injuries");Set(f,"selection",0);f.SavePreview(Path.Combine(evidence,"injuries-serious.png"));
  Simulation hop=null;for(int seed=0;seed<60;seed++){Simulation trial=ArcadeTests.Duel(5000+seed,.32f,false);trial.Update(1f/60,0,1);if(trial.HurdlesMade>0){hop=trial;break;}}if(hop!=null){Set(f,"game",hop);Set(f,"screen","game");Set(f,"cameraZ",19f);f.SavePreview(Path.Combine(evidence,"hurdle-cleared.png"));Check(hop.State==Phase.Live&&hop.Players[1].KnockTime>0,"successful hurdle visibly clears a DB");}else Check(false,"hurdle scene available");Set(f,"screen","home");Set(f,"matchFixture",-1);
 }
}
}
